DO $$
BEGIN
  UPDATE subscribers SET tier = 'platinum' WHERE lifetime_boxes >= 24;
  UPDATE subscribers SET tier = 'gold' WHERE lifetime_boxes >= 12 AND lifetime_boxes < 24;
  UPDATE subscribers SET churn_risk_flag = TRUE WHERE months_since_last_box >= 3;
  UPDATE subscribers SET retention_bonus = monthly_rate * 0.20 WHERE tier = 'platinum' AND churn_risk_flag = TRUE;
  UPDATE subscribers SET retention_bonus = monthly_rate * 0.10 WHERE tier = 'gold' AND churn_risk_flag = TRUE;
END $$;
SELECT * FROM subscribers ORDER BY subscriber_id;
